# ============================================================
# Script: 04_major_celltype_DE_analysis.R
# Project: Adipose scRNA-seq analysis
# Purpose: Perform major cell type-level differential expression analysis
# Author: Yi Hu
# ============================================================

# This script performs differential expression analysis between
# experimental conditions within each annotated major cell type.
# The annotated Seurat object is generated by 03_clustering_annotation.R.

# -----------------------------
# 1. Load packages
# -----------------------------

suppressPackageStartupMessages({
  library(Seurat)
  library(tidyverse)
  library(tibble)
})

# -----------------------------
# 2. Define input and output paths
# -----------------------------

input_file <- "results/annotation/seurat_integrated_annotated.rds"
output_dir <- "results/major_celltype_DE"

dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

# -----------------------------
# 3. Load annotated Seurat object
# -----------------------------

seurat_obj <- readRDS(input_file)

DefaultAssay(seurat_obj) <- "RNA"

# For Seurat v5 objects, join layers before differential expression if needed.
seurat_obj <- JoinLayers(seurat_obj)

# -----------------------------
# 4. Define comparison
# -----------------------------

condition_1 <- "HFSC"
condition_2 <- "Chow"

cell_types <- c(
  "ASPC",
  "Endothelial Cell",
  "Macrophage",
  "B Cell",
  "T Cell",
  "Mesothelial Cell",
  "Dendritic Cell",
  "Neutrophil"
)

# If Smooth Muscle Cell was included in the final annotation, add:
# "Smooth Muscle Cell"

# -----------------------------
# 5. Create DE grouping variable
# -----------------------------

# Example values:
# Macrophage-HFSC, Macrophage-Chow, ASPC-HFSC, ASPC-Chow

seurat_obj$DE_group <- paste0(
  seurat_obj$cell_type,
  "-",
  seurat_obj$condition
)

seurat_obj$DE_group <- factor(seurat_obj$DE_group)

Idents(seurat_obj) <- "DE_group"

# -----------------------------
# 6. Run DE analysis within each major cell type
# -----------------------------

de_results_list <- list()

for (cell_type in cell_types) {
  
  message("Running DE analysis for: ", cell_type)
  
  ident_1 <- paste(cell_type, condition_1, sep = "-")
  ident_2 <- paste(cell_type, condition_2, sep = "-")
  
  # Skip cell types that are not present in both conditions.
  if (!(ident_1 %in% levels(Idents(seurat_obj))) ||
      !(ident_2 %in% levels(Idents(seurat_obj)))) {
    
    warning("Skipping ", cell_type, ": one or both comparison groups are missing.")
    next
  }
  
  markers <- FindMarkers(
    object = seurat_obj,
    ident.1 = ident_1,
    ident.2 = ident_2,
    logfc.threshold = 0,
    min.pct = 0.1,
    test.use = "wilcox"
  )
  
  markers_df <- markers %>%
    as.data.frame() %>%
    rownames_to_column(var = "gene") %>%
    arrange(p_val_adj) %>%
    mutate(
      cell_type = cell_type,
      comparison = paste(condition_1, "vs", condition_2)
    )
  
  write.csv(
    markers_df,
    file = file.path(
      output_dir,
      paste0(gsub(" ", "_", cell_type), "_", condition_1, "_vs_", condition_2, "_DE.csv")
    ),
    row.names = FALSE
  )
  
  de_results_list[[cell_type]] <- markers_df
}

# -----------------------------
# 7. Combine DE results
# -----------------------------

combined_de_results <- bind_rows(de_results_list)

write.csv(
  combined_de_results,
  file = file.path(output_dir, "major_celltype_DE_combined.csv"),
  row.names = FALSE
)

# -----------------------------
# 8. Generate filtered DEG table
# -----------------------------

# This table can be used for pathway analysis input.
# Thresholds can be adjusted depending on the manuscript analysis plan.

deg_filtered <- combined_de_results %>%
  filter(
    p_val_adj < 0.05,
    abs(avg_log2FC) >= 0.25
  )

write.csv(
  deg_filtered,
  file = file.path(output_dir, "major_celltype_DE_filtered_FDR005_logFC025.csv"),
  row.names = FALSE
)

# -----------------------------
# 9. Save IPA input tables
# -----------------------------

ipa_output_dir <- file.path(output_dir, "IPA_input")
dir.create(ipa_output_dir, recursive = TRUE, showWarnings = FALSE)

for (cell_type in unique(deg_filtered$cell_type)) {
  
  ipa_table <- deg_filtered %>%
    filter(cell_type == !!cell_type) %>%
    select(gene, avg_log2FC, p_val, p_val_adj)
  
  write.csv(
    ipa_table,
    file = file.path(
      ipa_output_dir,
      paste0(gsub(" ", "_", cell_type), "_IPA_input.csv")
    ),
    row.names = FALSE
  )
}

# -----------------------------
# 10. Session information
# -----------------------------

sink(file.path(output_dir, "session_info_major_celltype_DE.txt"))
sessionInfo()
sink()